//! Failure paths of the store shim: whatever fails, the old store stays as it
//! was, no temporary file is left, and the lock is released.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::fs;
use std::os::unix::fs::PermissionsExt;
use std::path::PathBuf;
use std::time::Duration;

use todo::store::codec::Json;
use todo::store::lock::Patience;
use todo::store::{Store, StoreError};

/// A directory of its own under the build's temporary directory, removed when dropped.
struct TempDir(PathBuf);

impl TempDir {
    fn new(name: &str) -> Self {
        let path = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(format!("{name}-{}", std::process::id()));
        let _ = fs::remove_dir_all(&path);
        fs::create_dir_all(&path).unwrap();
        Self(path)
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = fs::set_permissions(&self.0, fs::Permissions::from_mode(0o755));
        let _ = fs::remove_dir_all(&self.0);
    }
}

fn quick(path: PathBuf) -> Store {
    Store::with_patience(path, Patience { every: Duration::from_millis(1), up_to: Duration::from_millis(50) })
}

fn leftovers(dir: &TempDir) -> Vec<String> {
    let mut names: Vec<String> =
        fs::read_dir(&dir.0).unwrap().map(|e| e.unwrap().file_name().to_string_lossy().into_owned()).collect();
    names.sort();
    names
}

/// The directory refuses new files: the write fails, the store and the directory are as they were.
#[test]
fn a_failed_write_leaves_the_old_store_and_no_temporary() {
    let dir = TempDir::new("unwritable");
    let path = dir.0.join("store.json");
    let store = quick(path.clone());
    store.update::<Json, _, _>(|_| Ok::<(), ()>(())).unwrap().unwrap();
    let before = fs::read(&path).unwrap();
    let mut changed = before.clone();
    changed.insert(0, b' ');
    fs::write(&path, &changed).unwrap(); // not canonical: the next update rewrites it
    fs::set_permissions(&dir.0, fs::Permissions::from_mode(0o555)).unwrap();
    let failed = store.update::<Json, _, _>(|_| Ok::<(), ()>(()));
    fs::set_permissions(&dir.0, fs::Permissions::from_mode(0o755)).unwrap();
    if !matches!(failed, Err(StoreError::Unwritable(_))) {
        // Run as a user the permission does not stop (root): nothing to show here.
        return;
    }
    assert_eq!(fs::read(&path).unwrap(), changed);
    assert_eq!(leftovers(&dir), ["store.json", "store.json.lock"]);
    // The lock was released with the failure: the next writer gets it at once.
    store.update::<Json, _, _>(|_| Ok::<(), ()>(())).unwrap().unwrap();
    assert_eq!(fs::read(&path).unwrap(), before);
}

/// A refusal writes nothing and releases the lock.
#[test]
fn a_refusal_writes_nothing_and_releases_the_lock() {
    let dir = TempDir::new("refusal");
    let path = dir.0.join("store.json");
    let store = quick(path.clone());
    assert_eq!(store.update::<Json, _, _>(|_| Err::<(), _>("refused")).unwrap(), Err("refused"));
    assert!(!path.exists());
    store.update::<Json, _, _>(|_| Ok::<(), ()>(())).unwrap().unwrap();
    assert!(path.exists());
    assert_eq!(leftovers(&dir), ["store.json", "store.json.lock"]);
}

/// An unreadable store is reported, never replaced, and the lock is released.
#[test]
fn an_unreadable_store_is_left_alone() {
    let dir = TempDir::new("unreadable");
    let path = dir.0.join("store.json");
    fs::write(&path, b"{not json\n").unwrap();
    let store = quick(path.clone());
    assert!(matches!(store.update::<Json, _, _>(|_| Ok::<(), ()>(())), Err(StoreError::Unreadable(_))));
    assert!(matches!(store.read::<Json>(), Err(StoreError::Unreadable(_))));
    assert_eq!(fs::read(&path).unwrap(), b"{not json\n");
    assert_eq!(leftovers(&dir), ["store.json", "store.json.lock"]);
}

/// A writer holding the lock makes the next one `Contended`, then lets it in once gone.
#[test]
fn the_lock_is_released_when_its_holder_returns() {
    let dir = TempDir::new("contended");
    let path = dir.0.join("store.json");
    let store = quick(path.clone());
    let inner = quick(path);
    let nested = store.update::<Json, _, _>(|_| Ok::<_, ()>(inner.update::<Json, _, _>(|_| Ok::<(), ()>(()))));
    assert!(matches!(nested, Ok(Ok(Err(StoreError::Contended)))));
    inner.update::<Json, _, _>(|_| Ok::<(), ()>(())).unwrap().unwrap();
}
